import{_ as a,o as n,c as e,S as l}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"如何瘦身docker镜像","description":"容器化部署已经成为现在的主流，打包 docker 镜像已经是现代前端开发的必修课了。最近正好在做新项目的时候处理过相关事情，所以记录一下。","frontmatter":{"title":"如何瘦身docker镜像","date":"2021-09-09 21:44","comments":true,"archives":2021,"tags":["docker"]},"headers":[],"relativePath":"posts/2021-09-09-slim-docker-image/index.md","filePath":"posts/2021/2021-09-09-slim-docker-image.md"}'),p={name:"posts/2021-09-09-slim-docker-image/index.md"};function o(r,s,c,t,i,d){return n(),e("div",null,[...s[0]||(s[0]=[l(`<p>容器化部署已经成为现在的主流，打包 docker 镜像已经是现代前端开发的必修课了。最近正好在做新项目的时候处理过相关事情，所以记录一下。</p><h2 id="docker-部署的需求" tabindex="-1">docker 部署的需求 <a class="header-anchor" href="#docker-部署的需求" aria-label="Permalink to &quot;docker 部署的需求&quot;">​</a></h2><p>首先我们需要使用 docker 完成网站源代码的编译，并且还要自己使用 <a href="https://expressjs.com/" target="_blank" rel="noreferrer">expressjs</a> 搭建服务器。让网站可以运行，docker 跑起来之后只用负责端口转发即可。</p><p>大家都知道前端网站编译需要安装很多依赖，但这些依赖在网站运行的时候并不需要。那如何才能做到，编译之后丢弃这些不用的依赖呢？ 我一开始尝试主动删除，但发现并没有减少 docker 的大小。</p><p>答案是<a href="https://docs.docker.com/develop/develop-images/multistage-build/" target="_blank" rel="noreferrer">Use multi-stage builds</a></p><h2 id="编译网站" tabindex="-1">编译网站 <a class="header-anchor" href="#编译网站" aria-label="Permalink to &quot;编译网站&quot;">​</a></h2><p>首先我们需要安装依赖并编译网站，dockerfile 内容如下：</p><div class="language-dockerfile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">FROM</span><span style="color:#24292E;"> node:14.17.5-buster-slim </span><span style="color:#D73A49;">as</span><span style="color:#24292E;"> build</span></span>
<span class="line"><span style="color:#D73A49;">ARG</span><span style="color:#24292E;"> GITHUB_PACKAGES_TOKEN</span></span>
<span class="line"><span style="color:#D73A49;">RUN</span><span style="color:#24292E;"> apt-get update &amp;&amp; apt-get install -y --no-install-recommends autoconf automake g++ libpng-dev make</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># use changes to package.json to force Docker not to use the cache</span></span>
<span class="line"><span style="color:#6A737D;"># when we change our application&#39;s nodejs dependencies:</span></span>
<span class="line"><span style="color:#D73A49;">COPY</span><span style="color:#24292E;"> package.json yarn.lock /tmp/</span></span>
<span class="line"><span style="color:#D73A49;">RUN</span><span style="color:#24292E;"> echo $GITHUB_PACKAGES_TOKEN</span></span>
<span class="line"><span style="color:#D73A49;">RUN</span><span style="color:#24292E;"> cd /tmp &amp;&amp; yarn install --forzen-lockfile --production=false</span></span>
<span class="line"><span style="color:#D73A49;">RUN</span><span style="color:#24292E;"> mkdir -p /app &amp;&amp; mv /tmp/node_modules /app</span></span>
<span class="line"><span style="color:#6A737D;"># From here we load our application&#39;s code in, therefore the previous docker</span></span>
<span class="line"><span style="color:#6A737D;"># &quot;layer&quot; thats been cached will be used if possible</span></span>
<span class="line"><span style="color:#D73A49;">WORKDIR</span><span style="color:#24292E;"> /app</span></span>
<span class="line"><span style="color:#D73A49;">COPY</span><span style="color:#24292E;"> . /app</span></span>
<span class="line"><span style="color:#D73A49;">ENV</span><span style="color:#24292E;"> NODE_ENV production</span></span>
<span class="line"><span style="color:#D73A49;">RUN</span><span style="color:#24292E;"> yarn build &amp;&amp; yarn express:build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>上面的命令编译了网站和 express 服务端代码，这里选择的 node 官方镜像并不是精简版，因为编译的时候需要很多依赖，精简版的话反而安装系统依赖更花时间。</p><h2 id="安装依赖" tabindex="-1">安装依赖 <a class="header-anchor" href="#安装依赖" aria-label="Permalink to &quot;安装依赖&quot;">​</a></h2><p>网站运行并不需要 node_modules 但是 express 服务器是需要的，所以我们需要安装后端的依赖。</p><div class="language-dockerfile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">FROM</span><span style="color:#24292E;"> node:14.17.5-alpine3.14 </span><span style="color:#D73A49;">as</span><span style="color:#24292E;"> deps</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># use changes to package.json to force Docker not to use the cache</span></span>
<span class="line"><span style="color:#6A737D;"># when we change our application&#39;s nodejs dependencies:</span></span>
<span class="line"><span style="color:#D73A49;">COPY</span><span style="color:#24292E;"> server/package.json server/yarn.lock /tmp/</span></span>
<span class="line"><span style="color:#D73A49;">RUN</span><span style="color:#24292E;"> cd /tmp &amp;&amp; yarn install --forzen-lockfile --production=false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>服务端的 <code>package.json</code> 文件我放在了 server 文件夹下，服务端依赖的东西很少，所以不太占用空间。</p><h2 id="打包实际生成的文件" tabindex="-1">打包实际生成的文件 <a class="header-anchor" href="#打包实际生成的文件" aria-label="Permalink to &quot;打包实际生成的文件&quot;">​</a></h2><div class="language-dockerfile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">FROM</span><span style="color:#24292E;"> node:14.17.5-alpine3.14</span></span>
<span class="line"><span style="color:#D73A49;">WORKDIR</span><span style="color:#24292E;"> /app</span></span>
<span class="line"><span style="color:#D73A49;">COPY</span><span style="color:#24292E;"> . /app</span></span>
<span class="line"><span style="color:#D73A49;">COPY</span><span style="color:#24292E;"> --from=deps /tmp/node_modules ./node_modules/</span></span>
<span class="line"><span style="color:#D73A49;">COPY</span><span style="color:#24292E;"> --from=build /app/dist ./dist/</span></span>
<span class="line"><span style="color:#D73A49;">COPY</span><span style="color:#24292E;"> --from=build /app/server ./server/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>接下来的步骤很简单了， 选择占用空间最小的 <code>Alpine Linux</code> 然后把编译好的文件复制进来就可以了。前两个步骤的所有东西都会被丢弃掉。所以实际生成的 docker 镜像会非常小。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>采用多阶段编译，可以有效的减少编译的依赖对空间的占用，做到最小化 docker 镜像。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://learnk8s.io/blog/smaller-docker-images" target="_blank" rel="noreferrer">3 simple tricks for smaller Docker images</a></p>`,20)])])}const u=a(p,[["render",o]]);export{b as __pageData,u as default};
